import sys
from collections import defaultdict

def read_int():
    return int(sys.stdin.readline())

def read_list_int():
    return list(map(int, sys.stdin.readline().split()))

def dfs(node, parent, graph, sizes):
    size = 1
    for neighbor in graph[node]:
        if neighbor != parent:
            sizes[node] += dfs(neighbor, node, graph, sizes)
            size += sizes[neighbor]
    return size

def find_good_subtree_size(n, edges):
    graph = defaultdict(list)
    for x, y in edges:
        graph[x].append(y)
        graph[y].append(x)

    sizes = [0] * (n + 1)
    dfs(1, -1, graph, sizes)

    max_size = 0
    for i in range(1, n + 1):
        max_size = max(max_size, sizes[i])

    return max_size

def main():
    q = read_int()
    results = []
    for _ in range(q):
        n = read_int()
        edges = [read_list_int() for _ in range(n - 1)]
        result = find_good_subtree_size(n, edges)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
